-- Zvky Pipeline Tracker — MySQL / MariaDB schema
--
-- Fresh install:
--   mysql -u <user> -p <database> < sql/schema.sql
--
-- On cPanel (GoDaddy), create the database and user first under
-- "MySQL Databases", then import this file through phpMyAdmin.
--
-- Ids are CHAR(36) UUIDs generated by the application, so this schema works
-- the same on MySQL 5.7, MySQL 8 and MariaDB.

SET NAMES utf8mb4;

-- --------------------------------------------------------------------------
-- Reference data: the value lists behind the dropdowns. These used to be
-- arrays in the source and CHECK constraints here, which meant a code change
-- and a deploy every time the studio wanted a new asset type or designation.
-- A Super Admin manages them in Settings; src/migrate.js fills them in from
-- the previous hardcoded values on first start.
--
-- `key` is what assets.type, assets.priority and users.role actually hold. It
-- is generated once and never changes, so renaming a value in Settings leaves
-- every record that uses it untouched. is_system marks the values the app
-- depends on by name and refuses to delete.
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS asset_types (
  id          CHAR(36)     NOT NULL PRIMARY KEY,
  `key`       VARCHAR(64)  NOT NULL,
  label       VARCHAR(100) NOT NULL,
  -- Asset codes are built from this: CHR-001, ENV-014.
  code_prefix VARCHAR(8)   NOT NULL,
  color       VARCHAR(16)  NULL,
  position    INT          NOT NULL DEFAULT 0,
  is_active   TINYINT(1)   NOT NULL DEFAULT 1,
  is_system   TINYINT(1)   NOT NULL DEFAULT 0,
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_asset_types_key (`key`),
  UNIQUE KEY uq_asset_types_prefix (code_prefix)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS priorities (
  id         CHAR(36)     NOT NULL PRIMARY KEY,
  `key`      VARCHAR(64)  NOT NULL,
  label      VARCHAR(100) NOT NULL,
  color      VARCHAR(16)  NULL,
  position   INT          NOT NULL DEFAULT 0,
  is_active  TINYINT(1)   NOT NULL DEFAULT 1,
  is_system  TINYINT(1)   NOT NULL DEFAULT 0,
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_priorities_key (`key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS roles (
  id         CHAR(36)     NOT NULL PRIMARY KEY,
  `key`      VARCHAR(64)  NOT NULL,
  label      VARCHAR(150) NOT NULL,
  -- The heading a role sits under in the picker: Art, Animation, Engineering.
  group_name VARCHAR(100) NOT NULL,
  -- Which capability set applies. See src/role-tiers.js.
  tier       VARCHAR(32)  NOT NULL,
  color      VARCHAR(16)  NULL,
  -- Doubles as seniority: higher sorts first within a group.
  position   INT          NOT NULL DEFAULT 0,
  is_active  TINYINT(1)   NOT NULL DEFAULT 1,
  is_system  TINYINT(1)   NOT NULL DEFAULT 0,
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_roles_key (`key`),
  KEY idx_roles_tier (tier)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- --------------------------------------------------------------------------
-- Which addresses may reach this application at all. Managed by a Super Admin
-- under Settings; enforced by src/middleware/ip-allowlist.js ahead of
-- authentication.
--
-- The ways back in after a bad entry live in the environment, not here — see
-- IP_ALLOWLIST_* in .env.example. A safeguard stored in the thing it safeguards
-- is not a safeguard.
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ip_allowlist (
  id               CHAR(36)     NOT NULL PRIMARY KEY,
  -- A single address or a CIDR range, stored canonically: 106.51.81.61,
  -- 106.51.81.0/24, 2001:db8::/32.
  address          VARCHAR(64)  NOT NULL,
  label            VARCHAR(120) NULL,
  is_active        TINYINT(1)   NOT NULL DEFAULT 1,
  created_by_id    CHAR(36)     NULL,
  -- Kept alongside the id so the trail survives the account being deleted.
  created_by_email VARCHAR(191) NULL,
  created_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_ip_allowlist_address (address),
  KEY idx_ip_allowlist_active (is_active)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Every change, including removals. After a lockout the useful question is who
-- removed what, so this is deliberately append-only and outlives the entries.
CREATE TABLE IF NOT EXISTS ip_allowlist_audit (
  id          CHAR(36)     NOT NULL PRIMARY KEY,
  action      VARCHAR(24)  NOT NULL,
  address     VARCHAR(64)  NULL,
  label       VARCHAR(120) NULL,
  actor_id    CHAR(36)     NULL,
  actor_email VARCHAR(191) NULL,
  actor_ip    VARCHAR(64)  NULL,
  detail      VARCHAR(255) NULL,
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_ip_audit_created (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS users (
  id            CHAR(36)     NOT NULL PRIMARY KEY,
  `name`        VARCHAR(255) NOT NULL,
  email         VARCHAR(191) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  -- One of the keys in src/roles.js. Kept as a VARCHAR rather than an ENUM so
  -- the studio can add a designation without an schema migration; the API
  -- validates it against the role catalogue on every write.
  `role`        VARCHAR(64)  NOT NULL,
  -- Who created this account. Despite the name this is not a reporting line:
  -- it gates who may edit or remove the user ("you can only change users you
  -- added"). Left alone deliberately — see reports_to_id below.
  manager_id    CHAR(36)     NULL,
  -- The work hierarchy for contributors: who reviews their assets. Drives
  -- team-scoped permissions, so it is not the org chart either.
  team_lead_id  CHAR(36)     NULL,
  -- The org chart: who this person reports to. Separate from both of the above
  -- because changing an org chart must not change anybody's permissions, and
  -- it applies to every designation rather than only to contributors.
  -- NULL for the Leadership tier, who sit at the top and report to no one.
  reports_to_id CHAR(36)     NULL,
  -- Unix epoch seconds, not DATETIME: this is compared against a JWT's `iat`
  -- claim, and epoch seconds carry no timezone for the two to disagree about.
  -- Any token issued before this moment is refused, which signs out every
  -- other device when someone changes their password.
  password_changed_at BIGINT UNSIGNED NULL,
  -- When this person finished or skipped the Quick Tour. NULL means they have
  -- never been shown it, which is what makes it launch itself once.
  --
  -- On the account rather than in the browser deliberately: it is a fact about
  -- a person, not about a machine. In localStorage it would replay for the same
  -- person on a second device and vanish when a browser is cleared, which is
  -- exactly the behaviour a "don't show this again" flag exists to prevent.
  tour_seen_at  DATETIME     NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_users_email (email),
  KEY idx_users_manager (manager_id),
  KEY idx_users_reports_to (reports_to_id),
  KEY idx_users_teamlead (team_lead_id),
  KEY idx_users_role (`role`),
  CONSTRAINT fk_users_manager   FOREIGN KEY (manager_id)   REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_users_team_lead FOREIGN KEY (team_lead_id) REFERENCES users(id) ON DELETE SET NULL,
  -- SET NULL rather than CASCADE: removing a manager must orphan their reports,
  -- never delete them.
  CONSTRAINT fk_users_reports_to FOREIGN KEY (reports_to_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- What each role may do. Every user's permissions come from their role, so a
-- change here moves everyone holding it together. See src/role-permissions.js.
--
-- The tier system underneath still carries what a checkbox cannot express:
-- projectScope, reviewStage and deleteAsset are values rather than booleans and
-- stay with the tier. This table is the booleans.
CREATE TABLE IF NOT EXISTS role_permissions (
  role_key         VARCHAR(64)  NOT NULL,
  permission_key   VARCHAR(64)  NOT NULL,
  enabled          TINYINT(1)   NOT NULL DEFAULT 0,
  updated_by_id    CHAR(36)     NULL,
  updated_by_email VARCHAR(191) NULL,
  updated_at       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (role_key, permission_key),
  KEY idx_role_permissions_role (role_key, enabled)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Who changed which permission for which role, and when. Append-only.
CREATE TABLE IF NOT EXISTS role_permission_audit (
  id             CHAR(36)     NOT NULL PRIMARY KEY,
  seq            BIGINT       NOT NULL AUTO_INCREMENT UNIQUE,
  role_key       VARCHAR(64)  NOT NULL,
  permission_key VARCHAR(64)  NOT NULL,
  action         VARCHAR(16)  NOT NULL,
  actor_id       CHAR(36)     NULL,
  actor_email    VARCHAR(191) NULL,
  created_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_role_perm_audit (role_key, seq)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Everything anybody did, in one place.
--
-- This is not a replacement for the four audit trails that already exist
-- (asset_events, role_permission_audit, ip_allowlist_audit, timesheet_events).
-- Those stay exactly as they are, and they stay the authority for their own
-- feature: an asset's history is read off asset_events, and it always will be.
-- They answer "what happened to THIS THING". This answers the different
-- question nobody could ask before — "what did this PERSON do", across
-- everything — and the two need different shapes, which is why merging them
-- would have made both worse.
--
-- The actor is denormalised on purpose. name, email and role are copied in at
-- the time of the action, so the entry still reads correctly after the account
-- is deleted and after somebody's designation changes. A log that says
-- "Ankita Das, Team Lead" must go on saying that even once Ankita is a Senior
-- Team Lead, or it is not a record of what happened.
CREATE TABLE IF NOT EXISTS activity_log (
  id           CHAR(36)     NOT NULL PRIMARY KEY,
  -- The order things happened in. created_at is accurate to the second and a
  -- bulk action lands many rows inside one, so this is what the page sorts on.
  -- Same reasoning as asset_events.seq, which had the same problem first.
  seq          BIGINT       NOT NULL AUTO_INCREMENT UNIQUE,
  actor_id     CHAR(36)     NULL,
  actor_name   VARCHAR(255) NULL,
  actor_email  VARCHAR(191) NULL,
  -- The designation held when this happened, not the one held now.
  actor_role   VARCHAR(64)  NULL,
  -- Which part of the app: assets, projects, users, permissions, timesheet,
  -- settings, auth. Used by the module filter, and the prefix of `action`.
  module       VARCHAR(32)  NOT NULL,
  -- What was done, as a stable key: asset.create, permission.grant, and so on.
  action       VARCHAR(64)  NOT NULL,
  -- What it was done to. entity_label is the human name at the time ("FX-001",
  -- "Project Alpha"), kept for the same reason the actor's name is.
  entity_type  VARCHAR(32)  NULL,
  entity_id    CHAR(36)     NULL,
  entity_label VARCHAR(255) NULL,
  -- One line a person can read without knowing the schema.
  summary      VARCHAR(500) NOT NULL,
  -- What changed, as {field: {from, to}}. JSON rather than two columns because
  -- one action can change several fields at once, and a row per field would
  -- turn one edit into five entries in a timeline read by humans.
  changes      TEXT         NULL,
  -- The request behind it, which is what makes an entry traceable back to code.
  method       VARCHAR(8)   NULL,
  path         VARCHAR(255) NULL,
  created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  -- The three ways the page reads this table: newest first, one person's
  -- actions, and one module's. Indexed because this is the table that grows
  -- without limit and the only one whose queries will get slower every month.
  KEY idx_activity_seq (seq),
  KEY idx_activity_actor (actor_id, seq),
  KEY idx_activity_module (module, seq),
  KEY idx_activity_when (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Who the work is for. A project belongs to exactly one client.
--
-- One row is a system client, "Unassigned": it exists so that projects created
-- before clients did have somewhere to belong, and so that projects.client_id
-- can be NOT NULL rather than nullable-and-usually-null. It can be renamed but
-- not deleted, because deleting it would orphan whatever is still in it.
CREATE TABLE IF NOT EXISTS clients (
  id            CHAR(36)     NOT NULL PRIMARY KEY,
  `name`        VARCHAR(255) NOT NULL,
  contact_name  VARCHAR(255) NULL,
  contact_email VARCHAR(191) NULL,
  notes         TEXT         NULL,
  -- Set on the "Unassigned" client only. A system client cannot be deleted.
  is_system     TINYINT(1)   NOT NULL DEFAULT 0,
  -- Archived, following the same convention the value lists use: something with
  -- records attached is deactivated rather than deleted, and everything under
  -- it keeps working. Hard delete stays available for a client holding nothing.
  is_active     TINYINT(1)   NOT NULL DEFAULT 1,
  archived_at   DATETIME     NULL,
  -- The engagement. NULL means the deal is live; a timestamp means it is closed
  -- and no new projects go under this client. Deliberately not a flag: "when"
  -- is the question anybody asks about a closed deal.
  deal_closed_at DATETIME    NULL,
  created_by    CHAR(36)     NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_clients_name (`name`),
  CONSTRAINT fk_clients_creator FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS projects (
  id         CHAR(36)     NOT NULL PRIMARY KEY,
  `name`     VARCHAR(255) NOT NULL,
  `code`     VARCHAR(64)  NULL,
  -- Required. Everything belongs to a client, even if that client is the
  -- system "Unassigned" one.
  client_id  CHAR(36)     NOT NULL,
  owner_id   CHAR(36)     NOT NULL,
  -- Archived, as above: the assets, their submissions and their review history
  -- are all still there, the project is simply out of the way.
  is_active  TINYINT(1)   NOT NULL DEFAULT 1,
  archived_at DATETIME    NULL,
  -- Closed. NULL means open. A closed project takes no new assets and its
  -- existing ones are read-only until it is reopened.
  closed_at  DATETIME     NULL,
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_projects_owner (owner_id),
  KEY idx_projects_client (client_id),
  KEY idx_projects_active (is_active),
  CONSTRAINT fk_projects_owner  FOREIGN KEY (owner_id)  REFERENCES users(id) ON DELETE CASCADE,
  -- RESTRICT, not CASCADE: deleting a client must never silently delete the
  -- projects under it, and with them every asset in those projects. The API
  -- refuses to delete a client that still holds work.
  CONSTRAINT fk_projects_client FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS project_team_leads (
  project_id CHAR(36) NOT NULL,
  user_id    CHAR(36) NOT NULL,
  PRIMARY KEY (project_id, user_id),
  KEY idx_ptl_user (user_id),
  CONSTRAINT fk_ptl_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  CONSTRAINT fk_ptl_user    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS project_coordinators (
  project_id CHAR(36) NOT NULL,
  user_id    CHAR(36) NOT NULL,
  PRIMARY KEY (project_id, user_id),
  KEY idx_pc_user (user_id),
  CONSTRAINT fk_pc_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  CONSTRAINT fk_pc_user    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Supervision and creative direction on a project: the supervisor and the art
-- director answerable for its look, as opposed to the leads who review its work
-- and the coordinators who run it. Capped at two people, which the API enforces
-- -- the table itself will hold any number, because a limit written into a
-- primary key cannot be relaxed without a migration.
CREATE TABLE IF NOT EXISTS project_supervision (
  project_id CHAR(36) NOT NULL,
  user_id    CHAR(36) NOT NULL,
  PRIMARY KEY (project_id, user_id),
  KEY idx_ps_user (user_id),
  CONSTRAINT fk_ps_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  CONSTRAINT fk_ps_user    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Status pipeline:
--  not_started -> assigned -> in_progress -> pending_tl_review -> (tl_changes_requested <-> pending_tl_review)
--    -> pending_cd_review -> (cd_changes_requested <-> pending_cd_review)
--    -> approved_for_client -> delivered
-- Everyone else's project. Coordinators sit in project_coordinators and leads in
-- project_team_leads; contributors had no link to a project at all, so the
-- studio's artists could not be assigned to one. This is that link.
CREATE TABLE IF NOT EXISTS project_members (
  project_id CHAR(36) NOT NULL,
  user_id    CHAR(36) NOT NULL,
  PRIMARY KEY (project_id, user_id),
  KEY idx_pm_user (user_id),
  CONSTRAINT fk_pm_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
  CONSTRAINT fk_pm_user    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS assets (
  id            CHAR(36)     NOT NULL PRIMARY KEY,
  `code`        VARCHAR(64)  NOT NULL,
  `name`        VARCHAR(255) NOT NULL,
  `type`        VARCHAR(32)  NOT NULL,
  `status`      VARCHAR(32)  NOT NULL DEFAULT 'not_started',
  priority      VARCHAR(8)   NOT NULL DEFAULT 'med',
  project_id    CHAR(36)     NOT NULL,
  assignee_id   CHAR(36)     NULL,
  -- Whose desk this is on right now, which is not the same as its status: an
  -- asset in CD Feedbacks sits with the team lead until they relay the notes, and
  -- with the assignee afterwards, without the status moving. NULL means a
  -- review queue that whoever holds that gate picks up.
  routed_to_id  CHAR(36)     NULL,
  -- Who added this asset. "Asset Edit" granted to a role means "edit the assets
  -- you added", not "edit the studio's assets", so ownership has to be a fact
  -- about the row rather than something inferred from the history.
  --
  -- Nullable, and NULL means unowned: rows that predate this column and could
  -- not be attributed. An unowned asset is editable only by a full-access role
  -- or by whoever it is assigned to.
  created_by    CHAR(36)     NULL,
  man_hours     DECIMAL(6,1) NULL,
  due_date      DATE         NULL,
  description   TEXT         NULL,
  -- The brief: a link to the requirement, reference art, or spec that the work
  -- is made FROM. Deliberately not the same thing as asset_versions.link, which
  -- is where a finished submission was put — one is the input, the other the
  -- output, and conflating them would make "the link" ambiguous on a screen
  -- that shows both. Optional, unlike a submission's link.
  reference_link VARCHAR(2048) NULL,
  -- What the lead or supervisor wants whoever picks this up to know, or wants
  -- on the record for the other leads. Separate from `description`, which is
  -- the brief everyone including the assignee reads and edits; this one is
  -- gated on the asset.lead_notes permission.
  --
  -- Its own column rather than a second use of description, because folding the
  -- two together would have meant either notes nobody could restrict or a
  -- Description artists could suddenly no longer see — and the second is taking
  -- a field away from people who have it today.
  lead_notes    TEXT         NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_assets_project (project_id),
  KEY idx_assets_assignee (assignee_id),
  KEY idx_assets_status (`status`),
  KEY idx_assets_routed (routed_to_id),
  KEY idx_assets_creator (created_by),
  CONSTRAINT fk_assets_project  FOREIGN KEY (project_id)  REFERENCES projects(id) ON DELETE CASCADE,
  CONSTRAINT fk_assets_assignee FOREIGN KEY (assignee_id) REFERENCES users(id)    ON DELETE SET NULL,
  CONSTRAINT fk_assets_routed   FOREIGN KEY (routed_to_id) REFERENCES users(id)   ON DELETE SET NULL,
  -- SET NULL rather than CASCADE: deleting the person who added an asset must
  -- not delete the asset. It becomes unowned, which is the safe end of the rule.
  CONSTRAINT fk_assets_creator  FOREIGN KEY (created_by)  REFERENCES users(id)   ON DELETE SET NULL,
  -- No CHECK on `type` or priority: both are managed in Settings and validated
  -- against the asset_types / priorities tables. `status` keeps its constraint
  -- because it is a fixed pipeline, not a list anyone edits.
  CONSTRAINT chk_assets_status CHECK (`status` IN (
    'not_started','assigned','in_progress','pending_tl_review','tl_changes_requested',
    'pending_cd_review','cd_changes_requested','approved_for_client','awaiting_client_feedback','delivered'
  ))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- The per-asset checklist. One table, not two: an "AssetTask" alongside this
-- would be a second name for the thing already here, and every screen would
-- then have to ask which kind it was looking at.
-- When somebody actually worked on an asset, one row per stretch of the clock.
--
-- A running stretch has ended_at NULL; pausing (or submitting, which pauses)
-- closes it and stamps seconds. The rule that keeps this honest: at most one
-- open row per asset, enforced by the API before it opens one — which is also
-- what makes a double-click or a second browser tab harmless.
--
-- `round` is which spell of work this was: 1 up to the first submission, 2 for
-- the rework after the first set of change requests, and so on. Stored rather
-- than derived so the per-round breakdown survives resubmissions and
-- reassignment mid-round.
CREATE TABLE IF NOT EXISTS work_sessions (
  id         CHAR(36)  NOT NULL PRIMARY KEY,
  asset_id   CHAR(36)  NOT NULL,
  user_id    CHAR(36)  NULL,
  round      INT       NOT NULL DEFAULT 1,
  -- Which stretch-with-one-person this session belongs to (asset_assignments).
  -- No foreign key: that table is declared after this one, and the link is a
  -- lookup rather than a rule worth failing a CREATE over. NULL on sessions
  -- written before assignment episodes existed.
  assignment_id CHAR(36) NULL,
  started_at DATETIME  NOT NULL DEFAULT CURRENT_TIMESTAMP,
  ended_at   DATETIME  NULL,
  -- Stamped when the row closes, so totals are a SUM rather than N date
  -- subtractions. NULL means the clock is still running.
  seconds    INT       NULL,
  KEY idx_ws_asset (asset_id),
  KEY idx_ws_open (asset_id, ended_at),
  KEY idx_ws_assignment (assignment_id),
  CONSTRAINT fk_ws_asset FOREIGN KEY (asset_id) REFERENCES assets(id) ON DELETE CASCADE,
  CONSTRAINT fk_ws_user  FOREIGN KEY (user_id)  REFERENCES users(id)  ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS tasks (
  id         CHAR(36)     NOT NULL PRIMARY KEY,
  asset_id   CHAR(36)     NOT NULL,
  `name`     VARCHAR(255) NOT NULL,
  done       TINYINT(1)   NOT NULL DEFAULT 0,
  `position` INT          NOT NULL DEFAULT 0,
  -- NULL on the three tasks every asset is seeded with, which nobody typed.
  created_by CHAR(36)     NULL,
  created_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_tasks_asset (asset_id),
  CONSTRAINT fk_tasks_asset  FOREIGN KEY (asset_id)   REFERENCES assets(id) ON DELETE CASCADE,
  CONSTRAINT fk_tasks_author FOREIGN KEY (created_by) REFERENCES users(id)  ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS notes (
  id         CHAR(36) NOT NULL PRIMARY KEY,
  asset_id   CHAR(36) NOT NULL,
  author_id  CHAR(36) NULL,
  `text`     TEXT     NOT NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_notes_asset (asset_id),
  CONSTRAINT fk_notes_asset  FOREIGN KEY (asset_id)  REFERENCES assets(id) ON DELETE CASCADE,
  CONSTRAINT fk_notes_author FOREIGN KEY (author_id) REFERENCES users(id)  ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Every file an artist uploads for review is a version. stage records which
-- review loop it was submitted into, so reviewers see the right history.
CREATE TABLE IF NOT EXISTS asset_versions (
  id             CHAR(36)     NOT NULL PRIMARY KEY,
  asset_id       CHAR(36)     NOT NULL,
  version_number INT          NOT NULL,
  stage          VARCHAR(8)   NOT NULL,
  -- Where the work is. Mandatory for anything submitted through the review
  -- form; NULL only on rows that predate it and carry a file instead.
  link           VARCHAR(2048) NULL,
  -- The submitter's own notes. Optional by design: a link with nothing to say
  -- about it is a perfectly ordinary submission.
  description    TEXT         NULL,
  -- Kept for submissions made before the form took a link, and still allowed
  -- as an optional attachment alongside one.
  file_name      VARCHAR(255) NULL,
  file_path      VARCHAR(255) NULL,
  file_size      INT          NULL,
  uploaded_by    CHAR(36)     NULL,
  created_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_versions_asset (asset_id),
  CONSTRAINT fk_versions_asset  FOREIGN KEY (asset_id)    REFERENCES assets(id) ON DELETE CASCADE,
  CONSTRAINT fk_versions_author FOREIGN KEY (uploaded_by) REFERENCES users(id)  ON DELETE SET NULL,
  CONSTRAINT chk_versions_stage CHECK (stage IN ('tl','cd'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- A reviewer's decision on a version: approve, or request changes with notes.
-- Every move an asset makes, in order: assignment, each submission, each review
-- decision, the relay, delivery. The submission and review tables hold the
-- detail; this holds the sequence, so the asset detail view can show the whole
-- back-and-forth rather than only the current state.
--
-- Append-only. Nothing here is ever updated or deleted while the asset lives.
-- One row per stretch of time an asset sat with one person.
--
-- The asset's own row says who has it NOW. This says who has had it, in order,
-- and it is what the Assets List is built from: a reassignment adds a row here
-- rather than overwriting the last one, so the person who did the first round
-- keeps their line, their time and their submission.
--
-- An episode opens whenever the assignee changes and closes when it changes
-- again. At most one is open per asset at a time — the same invariant
-- work_sessions keeps for the clock, and for the same reason.
CREATE TABLE IF NOT EXISTS asset_assignments (
  id            CHAR(36)     NOT NULL PRIMARY KEY,
  seq           BIGINT       NOT NULL AUTO_INCREMENT UNIQUE,
  asset_id      CHAR(36)     NOT NULL,
  -- Null only if the asset was unassigned; an episode with nobody in it is not
  -- written, so in practice this is always somebody.
  user_id       CHAR(36)     NULL,
  assigned_by_id CHAR(36)    NULL,
  assigned_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  -- Where the asset was when this person got it. A reassignment out of TL
  -- Review reads 'pending_tl_review' here even though the asset moves to
  -- 'assigned' for the new person, which is what makes the trail legible.
  status_at_assignment VARCHAR(32) NOT NULL,
  ended_at      DATETIME     NULL,
  -- Where the asset had got to when this person let go of it. The Assets List
  -- shows this on a finished row: somebody who took work all the way to TL
  -- Review should not have their round labelled with the status it started in.
  ended_status  VARCHAR(32)  NULL,
  -- Why it ended: 'reassigned', 'unassigned', 'delivered'.
  ended_reason  VARCHAR(32)  NULL,
  KEY idx_aa_asset (asset_id, seq),
  KEY idx_aa_open (asset_id, ended_at),
  CONSTRAINT fk_aa_asset FOREIGN KEY (asset_id) REFERENCES assets(id) ON DELETE CASCADE,
  CONSTRAINT fk_aa_user  FOREIGN KEY (user_id)  REFERENCES users(id)  ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- One row per bulk action, so "who delivered these twelve, and when" is a
-- question with an answer. The per-asset events below still carry the whole
-- story of each asset on their own; this says which of them were one act.
--
-- Deliberately not a replacement for those events: a bulk delivery writes a
-- normal 'deliver' event per asset, through the same transition a single
-- delivery uses, and only additionally points them at a batch.
-- A whole project put in front of the Creative Director, as opposed to one
-- asset moving through the review pipeline.
--
-- Deliberately its own table and NOT a status on assets. It is a different kind
-- of thing: a link to something — a deck, a milestone build, a cut — that
-- concerns the project rather than any one asset in it, with no assignee, no
-- rounds and no place in the asset state machine. Modelling it as an asset
-- status would have put a review request in the same queue as the work itself
-- and made "CD Review" mean two things.
CREATE TABLE IF NOT EXISTS project_review_requests (
  id           CHAR(36)      NOT NULL PRIMARY KEY,
  client_id    CHAR(36)      NOT NULL,
  project_id   CHAR(36)      NOT NULL,
  link         VARCHAR(2048) NOT NULL,
  description  TEXT          NULL,
  -- Who asked, kept alongside the id so the record survives the account going.
  submitted_by CHAR(36)      NULL,
  submitter_email VARCHAR(191) NULL,
  -- 'pending' until the Creative Director answers it, then 'feedback_given'.
  -- Nothing is deleted: an answered request stays as the record that it was
  -- asked for and answered.
  --
  -- Rows may also carry 'changes_requested' or 'approved_for_client'. Those are
  -- from when the answer was a choice between two buttons; one Submit Feedback
  -- replaced them, and the old rows are left alone because somebody really did
  -- make that decision. Everything answered is treated alike from here on.
  --
  -- These are the SUBMISSION's states and share nothing with the asset statuses
  -- of similar name. No asset moves when one of these is set — Production reads
  -- the feedback and decides which assets, if any, it applies to.
  status       VARCHAR(32)   NOT NULL DEFAULT 'pending',
  -- What the Creative Director wrote. Required, now that it is the entire
  -- content of their answer: with one button and no status to read, an empty
  -- note would tell Production only that somebody had looked.
  feedback     TEXT          NULL,
  -- Who answered it and when. Named 'reviewed' because that is what the columns
  -- have always been called here; the decision itself is in `status`.
  reviewed_by  CHAR(36)      NULL,
  reviewer_email VARCHAR(191) NULL,
  reviewed_at  DATETIME      NULL,
  -- Production, saying they have dealt with the Creative Director's answer:
  -- routed the changes to the assets they apply to, or taken the approval on.
  --
  -- A step of its own rather than something inferred, because there is nothing
  -- to infer it from. The submission names no asset, and the reassignment flow
  -- Production uses knows nothing about the submission that prompted it — so
  -- the only honest signal that this has been handled is somebody saying so.
  closed_by    CHAR(36)      NULL,
  closer_email VARCHAR(191)  NULL,
  closed_at    DATETIME      NULL,
  -- The submitter, saying they have read the answer they asked for.
  --
  -- Deliberately NOT a status value. `status` is the submission's own state and
  -- every role reads it; acknowledgement is one person's completion marker,
  -- exactly as closed_at is Production's. Modelling it as a status would have
  -- made one person finishing with a row change what everybody else sees of it.
  --
  -- Its own step for the same reason closed_at is: the only honest signal that
  -- somebody has read something is that somebody says so.
  acknowledged_by    CHAR(36)     NULL,
  acknowledger_email VARCHAR(191) NULL,
  acknowledged_at    DATETIME     NULL,
  created_at   DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_prr_status (status, created_at),
  KEY idx_prr_project (project_id),
  CONSTRAINT fk_prr_client   FOREIGN KEY (client_id)    REFERENCES clients(id)  ON DELETE CASCADE,
  CONSTRAINT fk_prr_project  FOREIGN KEY (project_id)   REFERENCES projects(id) ON DELETE CASCADE,
  CONSTRAINT fk_prr_submitter FOREIGN KEY (submitted_by) REFERENCES users(id)   ON DELETE SET NULL,
  CONSTRAINT fk_prr_reviewer FOREIGN KEY (reviewed_by)  REFERENCES users(id)    ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- The preview image on an asset's card.
--
-- A table of its own rather than columns on `assets`, and that is the whole
-- point of it. The board reads assets with SELECT a.* — so a MEDIUMBLOB on
-- that row would be re-encoded as a JSON array of byte values into every
-- board response, for every asset on it. That is exactly the bug
-- src/user-fields.js was written to fix after SELECT * put a profile photo
-- into every sign-in response.
--
-- Naming the columns instead would work until somebody adds the next blob.
-- Keeping the bytes in a table nothing joins by default makes the mistake
-- unavailable rather than merely avoided: the board joins this for its
-- updated_at and never for its image.
CREATE TABLE IF NOT EXISTS asset_thumbnails (
  asset_id   CHAR(36)     NOT NULL PRIMARY KEY,
  image      MEDIUMBLOB   NOT NULL,
  mime       VARCHAR(64)  NOT NULL,
  -- Who last changed it, kept with the email so the record survives the
  -- account going, as the other trails in this schema do.
  updated_by CHAR(36)     NULL,
  updater_email VARCHAR(191) NULL,
  -- The page appends this to the image URL, so a replacement is a new URL and
  -- appears at once rather than sitting behind a cached copy of the old one.
  updated_at DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_thumb_asset FOREIGN KEY (asset_id) REFERENCES assets(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS asset_event_batches (
  id          CHAR(36)     NOT NULL PRIMARY KEY,
  action      VARCHAR(32)  NOT NULL,
  actor_id    CHAR(36)     NULL,
  -- Kept alongside the id so the record survives the account being deleted,
  -- the same bargain asset_events makes.
  actor_email VARCHAR(191) NULL,
  -- What was asked for and what happened, so a partly-failed batch is legible
  -- without replaying every event under it.
  requested   INT          NOT NULL DEFAULT 0,
  succeeded   INT          NOT NULL DEFAULT 0,
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_batches_actor (actor_id, created_at),
  CONSTRAINT fk_batches_actor FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS asset_events (
  id          CHAR(36)     NOT NULL PRIMARY KEY,
  -- The order things happened in. created_at is only accurate to the second,
  -- and a review round is quicker than that — submit, approve and relay land in
  -- the same second routinely, and sorting by timestamp then scrambles them.
  -- This is the sequence the history is read in.
  seq         BIGINT       NOT NULL AUTO_INCREMENT UNIQUE,
  asset_id    CHAR(36)     NOT NULL,
  -- The transition that was made: assign, reassign, submit, tl_approve,
  -- tl_request_changes, cd_approve, cd_request_changes, relay, deliver.
  action      VARCHAR(32)  NOT NULL,
  from_status VARCHAR(32)  NULL,
  to_status   VARCHAR(32)  NOT NULL,
  actor_id    CHAR(36)     NULL,
  -- Kept alongside the id so the trail survives the account being deleted.
  actor_email VARCHAR(191) NULL,
  -- Feedback text, or the submitter's description, or a plain explanation.
  note        TEXT         NULL,
  -- The submission this event concerns, when there is one.
  version_id  CHAR(36)     NULL,
  routed_to_id CHAR(36)    NULL,
  -- The bulk action this event was part of, when it was part of one. NULL for
  -- everything done one asset at a time, which is nearly everything.
  batch_id    CHAR(36)     NULL,
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_events_asset (asset_id, seq),
  KEY idx_events_batch (batch_id),
  CONSTRAINT fk_events_asset  FOREIGN KEY (asset_id)   REFERENCES assets(id)         ON DELETE CASCADE,
  CONSTRAINT fk_events_actor  FOREIGN KEY (actor_id)   REFERENCES users(id)          ON DELETE SET NULL,
  CONSTRAINT fk_events_version FOREIGN KEY (version_id) REFERENCES asset_versions(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS feedback (
  id         CHAR(36)   NOT NULL PRIMARY KEY,
  asset_id   CHAR(36)   NOT NULL,
  version_id CHAR(36)   NULL,
  stage      VARCHAR(8) NOT NULL,
  decision   VARCHAR(24) NOT NULL,
  given_by   CHAR(36)   NULL,
  `text`     TEXT       NULL,
  created_at DATETIME   NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_feedback_asset (asset_id),
  CONSTRAINT fk_feedback_asset   FOREIGN KEY (asset_id)   REFERENCES assets(id)         ON DELETE CASCADE,
  CONSTRAINT fk_feedback_version FOREIGN KEY (version_id) REFERENCES asset_versions(id) ON DELETE SET NULL,
  CONSTRAINT fk_feedback_author  FOREIGN KEY (given_by)   REFERENCES users(id)          ON DELETE SET NULL,
  CONSTRAINT chk_feedback_stage    CHECK (stage IN ('tl','cd')),
  CONSTRAINT chk_feedback_decision CHECK (decision IN ('approved','changes_requested'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- The manual timesheet: what somebody says they worked on, as opposed to what
-- the app watched them do.
--
-- Deliberately separate from work_sessions, and the separation is the point.
-- work_sessions is measured — the clock between Accept and Submit on one asset —
-- and it is what the Efficiency and Idle reports read. This is declared: a
-- person's own account of their day, including the parts that are not an asset
-- at all. Feeding one into the other would make "Time Spent" mean two things,
-- and neither report would be trustworthy afterwards.
--
-- One row per week per person, holding where that week has got to. The weekly
-- shape is what submission and approval act on: a week is submitted as a whole,
-- and approving half of one is not a thing a timesheet does.
CREATE TABLE IF NOT EXISTS timesheet_days (
  id           CHAR(36)     NOT NULL PRIMARY KEY,
  user_id      CHAR(36)     NOT NULL,
  -- One row per person per DAY. It was a week when this shipped; the studio
  -- moved the cycle to daily, which is not a setting but a different unit of
  -- the thing being approved — approving Tuesday and rejecting Wednesday is
  -- meaningless if the row is a week.
  work_date    DATE         NOT NULL,
  -- draft -> submitted -> approved | rejected, and rejected -> draft again on
  -- the next edit. The lines have no status of their own: they are locked or
  -- not by the day they sit in.
  status       VARCHAR(16)  NOT NULL DEFAULT 'draft',
  submitted_at DATETIME     NULL,
  decided_by   CHAR(36)     NULL,
  decider_email VARCHAR(191) NULL,
  decided_at   DATETIME     NULL,
  -- Required on a rejection: sending a day back without saying why asks
  -- somebody to guess at their own hours.
  rejection_reason TEXT     NULL,
  created_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY uq_tsd_user_day (user_id, work_date),
  KEY idx_tsd_status (status, work_date),
  CONSTRAINT fk_tsd_user    FOREIGN KEY (user_id)    REFERENCES users(id) ON DELETE CASCADE,
  CONSTRAINT fk_tsd_decider FOREIGN KEY (decided_by) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT chk_tsd_status CHECK (status IN ('draft','submitted','approved','rejected'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- One line of a day. Several per day is the normal case — three hours here, two
-- there — which is why this is a row per line and not a column per day.
CREATE TABLE IF NOT EXISTS timesheet_entries (
  id          CHAR(36)     NOT NULL PRIMARY KEY,
  user_id     CHAR(36)     NOT NULL,
  entry_date  DATE         NOT NULL,
  /* When, as minutes past midnight India Standard Time — 570 is 09:30.
   *
   * Minutes rather than a DATETIME, and this is the decision the whole
   * timezone requirement rests on. A timesheet time is a wall-clock time in
   * the studio, not an instant: stored as an instant it needs a zone to read
   * back, and the studio's 9:30 then lands at 04:00 for a server in UTC and at
   * 23:00 for somebody logging in from California. Stored as 570 it is 09:30
   * to everybody, on every machine, with no conversion anywhere. IST has no
   * daylight saving, so there is no second case to get wrong.
   *
   * The consequence, stated: these are NOT comparable with the asset
   * pipeline's timestamps, which are real instants. Same wall this feature
   * already has with the Efficiency report, and the right one. */
  start_min   SMALLINT     NOT NULL,
  end_min     SMALLINT     NOT NULL,
  -- All three optional, because a line is either project work or it is not.
  -- A project line carries client and project and may carry an asset; a
  -- non-project line carries none of them and carries a category instead. The
  -- API enforces that it is one or the other, since a row that is both is a row
  -- nobody can report on.
  client_id   CHAR(36)     NULL,
  project_id  CHAR(36)     NULL,
  asset_id    CHAR(36)     NULL,
  -- leave | holiday | meeting | training | admin. A fixed list rather than a
  -- Settings collection for now: five words that every studio uses the same
  -- way, and one fewer thing to configure before the feature works.
  non_project VARCHAR(32)  NULL,
  -- Derived from start_min and end_min with the lunch hour taken out, and
  -- stored so the totals, the exports and the approver's queue read one number
  -- instead of dividing by sixty in four places.
  hours       DECIMAL(5,2) NOT NULL,
  notes       TEXT         NULL,
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_tse_user_day (user_id, entry_date),
  KEY idx_tse_date (entry_date),
  KEY idx_tse_project (project_id),
  CONSTRAINT fk_tse_user    FOREIGN KEY (user_id)    REFERENCES users(id)    ON DELETE CASCADE,
  -- RESTRICT on none of these: a line pointing at something deleted becomes a
  -- line with a gap in it, which is better than losing the hours.
  CONSTRAINT fk_tse_client  FOREIGN KEY (client_id)  REFERENCES clients(id)  ON DELETE SET NULL,
  CONSTRAINT fk_tse_project FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE SET NULL,
  CONSTRAINT fk_tse_asset   FOREIGN KEY (asset_id)   REFERENCES assets(id)   ON DELETE SET NULL,
  CONSTRAINT chk_tse_hours  CHECK (hours > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Who did what to a timesheet. Hours are the input to somebody's pay, so every
-- edit, submission and decision is on the record — including edits a person
-- makes to their own week, which is exactly the thing a dispute turns on.
CREATE TABLE IF NOT EXISTS timesheet_events (
  id          CHAR(36)     NOT NULL PRIMARY KEY,
  seq         BIGINT       NOT NULL AUTO_INCREMENT UNIQUE,
  -- Whose sheet, which week. Not a foreign key to timesheet_weeks: the trail
  -- outlives the row it describes.
  user_id     CHAR(36)     NULL,
  work_date   DATE         NOT NULL,
  -- entry_added | entry_edited | entry_removed | submitted | approved | rejected
  action      VARCHAR(32)  NOT NULL,
  actor_id    CHAR(36)     NULL,
  actor_email VARCHAR(191) NULL,
  -- What changed, in words: the line and its hours, or the reason for a
  -- rejection. Read by people, not parsed.
  detail      TEXT         NULL,
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_tsev_sheet (user_id, work_date, seq),
  CONSTRAINT fk_tsev_user  FOREIGN KEY (user_id)  REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT fk_tsev_actor FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
